/*
 * A085192  First differences of A014486.
 * https://oeis.org/A085192
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A014486(n+1) - A014486(n), where A014486 lists Dyck words
 *            (as binary numbers) in increasing order, generated by recursion
 * Range:     u8 n <= 21, u16 n <= 2054, u32 n <= 23712, u64 n <= 23712,
 *            u128 n <= 23712, big any n
 * Validated: standard, pass, 109 terms through n = 9985 (2026-11-07)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/mem.h"

static seq_t *A014486_cache = NULL;
static size_t A014486_cache_size = 0;
static size_t A014486_cache_cap = 0;
static idx_t A014486_next_k = 1;

static void A014486_ensure(size_t need)
{
    if (need <= A014486_cache_cap)
        return;
    size_t newcap = A014486_cache_cap ? A014486_cache_cap * 2 : 16;
    while (newcap < need)
        newcap <<= 1;
    seq_t *p = mem_resize(seq_t, A014486_cache, newcap);
    if (!p)
        return;
    A014486_cache = p;
    A014486_cache_cap = newcap;
}

static void A014486_gen(int L, int pos, int ones, int zeros, seq_t cur)
{
    if (pos == L) {
        A014486_ensure(A014486_cache_size + 1);
        if (A014486_cache_cap >= A014486_cache_size + 1)
            A014486_cache[A014486_cache_size++] = cur;
        return;
    }
    if (zeros < ones && zeros < L / 2)
        A014486_gen(L, pos + 1, ones, zeros + 1, cur << 1);
    if (ones < L / 2)
        A014486_gen(L, pos + 1, ones + 1, zeros, (cur << 1) | 1);
}

static seq_t A014486_a(idx_t n)
{
    if (A014486_cache_size == 0) {
        A014486_cache_cap = 16;
        A014486_cache = mem_new(seq_t, A014486_cache_cap);
        if (!A014486_cache)
            return (seq_t)0;
        A014486_cache[0] = (seq_t)0;
        A014486_cache_size = 1;
    }
    if (n < (idx_t)A014486_cache_size)
        return A014486_cache[n];
    while (n >= (idx_t)A014486_cache_size) {
        int k = (int)A014486_next_k;
        A014486_gen(2 * k, 1, 1, 0, (seq_t)1);
        ++A014486_next_k;
    }
    return A014486_cache[n];
}

seq_t a(idx_t n)
{
    seq_t hi = A014486_a(n + 1);
    seq_t lo = A014486_a(n);
    return hi - lo;
}
